using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var build = BinaryLog.ReadBuild("build.binlog");

Console.WriteLine("=== BUILD RESULT: " + (build.Succeeded ? "SUCCESS" : "FAILED") + " ===\n");

// Collect all errors
var errors = new List<(string project, string code, string file, int line, string message)>();

build.VisitAllChildren<Error>(error => {
    string project = "";
    var node = error.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    errors.Add((project, error.Code ?? "", error.File ?? "", error.LineNumber, error.Text ?? error.ToString()));
});

// Also collect warnings that might be relevant
var warnings = new List<(string project, string code, string message)>();
build.VisitAllChildren<Warning>(w => {
    string project = "";
    var node = w.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    warnings.Add((project, w.Code ?? "", w.Text ?? w.ToString()));
});

Console.WriteLine($"Total errors: {errors.Count}");
Console.WriteLine($"Total warnings: {warnings.Count}\n");

Console.WriteLine("=== ERRORS ===");
foreach (var g in errors.GroupBy(e => e.project))
{
    Console.WriteLine($"\n--- Project: {g.Key} ---");
    foreach (var e in g)
    {
        Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
    }
}

if (warnings.Count > 0 && warnings.Count <= 30) {
    Console.WriteLine("\n=== WARNINGS ===");
    foreach (var g in warnings.GroupBy(w => w.project))
    {
        Console.WriteLine($"\n--- Project: {g.Key} ---");
        foreach (var w in g)
        {
            Console.WriteLine($"  [{w.code}] {w.message}");
        }
    }
}

// Check project dependency failures
Console.WriteLine("\n=== PROJECT BUILD RESULTS ===");
build.VisitAllChildren<Project>(p => {
    if (p.Children.OfType<Error>().Any() || !p.Succeeded)
    {
        Console.WriteLine($"  {(p.Succeeded ? "OK" : "FAILED")}: {p.Name} (target: {p.TargetFramework})");
    }
});
