using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var build = BinaryLog.ReadBuild("/tmp/sv-e5004a69ecde4d71a86a04374b1e2a1b/build.binlog");

// Extract source file contents from the binlog
Console.WriteLine("=== SOURCE FILES REFERENCED IN ERRORS ===\n");

// Look for the project file content and references
build.VisitAllChildren<Project>(p => {
    if (p.Name == "Services.csproj") {
        Console.WriteLine($"Project: {p.Name}");
        // Look for items/properties
        p.VisitAllChildren<Item>(item => {
            if (item.Name.Contains("Reference") || item.Name.Contains("Package"))
                Console.WriteLine($"  Item: {item.Name} = {item.Text}");
        });
        p.VisitAllChildren<AddItem>(item => {
            Console.WriteLine($"  AddItem: {item.Name} ({item.Children.Count} children)");
            foreach (var c in item.Children.Take(10))
                Console.WriteLine($"    -> {c}");
        });
    }
});

// Check all projects for dependency info
Console.WriteLine("\n=== ALL PROJECTS IN BUILD ===");
build.VisitAllChildren<Project>(p => {
    if (!string.IsNullOrEmpty(p.Name) && p.Name.EndsWith(".csproj"))
        Console.WriteLine($"  {p.Name} (TF: {p.TargetFramework})");
});

// Look for package restore info
Console.WriteLine("\n=== NUGET/PACKAGE INFO ===");
build.VisitAllChildren<Message>(m => {
    if (m.Text != null && (m.Text.Contains("Newtonsoft") || m.Text.Contains("PackageReference") || m.Text.Contains("package")))
        Console.WriteLine($"  {m.Text}");
});
